import{t as e}from"./refs.d_NoxLf7.js";var t={meta:{title:`Venite ad me`,subtitle:{zh:`在時代變遷中傳遞信仰的省思`,en:`Considerations on the Transmission of the Faith in an Epochal Change`},siteName:{zh:`光的旅程`,en:`The Journey of Light`},issuer:{zh:`教義部`,en:`Dicastery for the Doctrine of the Faith`},date:`2026-10-22`,approved:`2026-08-21`,paragraphs:144,sourceUrl:e,seed:20261022},chapters:[{id:`intro`,num:`導言`,guideUrl:`/venite-ad-me/guide/intro`,range:[1,8],title:{zh:`導言`,en:`Introduction`},notes:{zh:`§1 是書名經句（瑪 11:28）；§8 說明文體是「省思」，不是「教義註釋」。`,en:`§1 is the title verse (Mt 11:28); §8 says the genre is 'Considerations', not a Doctrinal Note.`}},{id:`1`,num:`I`,guideUrl:`/venite-ad-me/guide/1`,range:[9,23],site:[`sun`],title:{zh:`父愛的宣講`,en:`The Proclamation of the Father's Love`}},{id:`2`,num:`II`,guideUrl:`/venite-ad-me/guide/2`,range:[24,42],site:[`family`,`community`],title:{zh:`信仰之光`,en:`The Light of Faith`},sections:[{from:30,title:{zh:`信仰傳遞的形式`,en:`Forms of Transmitting the Faith`}},{from:31,title:{zh:`家庭`,en:`The Family`}},{from:39,title:{zh:`教會團體`,en:`The Ecclesial Community`}}]},{id:`3`,num:`III`,guideUrl:`/venite-ad-me/guide/3`,range:[43,71],site:[`dayCycle`,`digital`,`voices`],title:{zh:`時代變遷`,en:`The Epochal Change`},sections:[{from:47,title:{zh:`信仰傳遞的危機`,en:`The Crisis in the Transmission of the Faith`}},{from:54,title:{zh:`一種新的、普遍的文化`,en:`A New, Widespread Culture`}},{from:59,title:{zh:`數位科技`,en:`Digital Technologies`}},{from:63,title:{zh:`福傳的新邊疆`,en:`New Frontiers of Evangelization`}}]},{id:`4`,num:`IV`,guideUrl:`/venite-ad-me/guide/4`,range:[72,86],site:[`kerygma`],title:{zh:`初傳的核心地位`,en:`Centrality of the Kerygma`},sections:[{from:75,title:{zh:`促成信仰的經驗`,en:`Fostering an Experience of Faith`}},{from:80,title:{zh:`語言的問題`,en:`The Question of Language`}},{from:83,title:{zh:`基督徒培育`,en:`Christian Formation`}}]},{id:`5`,num:`V`,guideUrl:`/venite-ad-me/guide/5`,range:[87,101],site:[`community`,`liturgy`,`witness`,`beauty`,`lifestages`],title:{zh:`團體中的信仰傳遞`,en:`The Transmission of the Faith in Communities`},sections:[{from:90,title:{zh:`禮儀`,en:`Liturgy`}},{from:95,title:{zh:`見證的角色`,en:`The Role of Witness`}},{from:98,title:{zh:`藝術與美`,en:`Art and Beauty`}},{from:100,title:{zh:`人生的各個階段`,en:`The Stages of Life`}}]},{id:`6`,num:`VI`,guideUrl:`/venite-ad-me/guide/6`,range:[102,109],site:[`culture`],title:{zh:`信仰與文化`,en:`Faith and Culture`}},{id:`7`,num:`VII`,guideUrl:`/venite-ad-me/guide/7`,range:[110,123],title:{zh:`若干特定關注領域`,en:`Some Specific Areas of Attention`},areas:[{id:`popular-piety`,ref:[111,112],island:`culture`,zh:`培育民間敬禮：它至今仍是傳遞信仰的重要途徑`,en:`Cultivate popular piety, still an important way of handing on the faith`},{id:`pilgrimage`,ref:[113],island:`culture`,zh:`看見青年對朝聖與善會的嚮往，讓它成為基督之光的管道`,en:`Young people's draw to pilgrimages and confraternities can become a channel for Christ's light`},{id:`homily`,ref:[114],island:`kerygma`,zh:`講道：用敘事，從人的具體生活重新讀天主的話`,en:`The homily: narrative preaching that rereads the Word in light of people's lives`},{id:`volunteers`,ref:[115],island:`witness`,zh:`接待投入志工服務的人——這個時代的「善心撒瑪黎雅人」`,en:`Welcome volunteers, today's 'Good Samaritans'`},{id:`women`,ref:[116],island:`community`,zh:`擴大婦女參與教會決策與領導的機會`,en:`Widen women's participation in ecclesial leadership and decisions`},{id:`events`,ref:[117],island:`community`,zh:`大型聚會顯示人渴望陪伴；可圍繞和平等時代主題創造相聚的場合`,en:`Large events show a hunger for companionship; gather people around themes like peace`},{id:`history`,ref:[118,119],island:null,zh:`向教會史學習：教會史上幾次時代轉換的危機，都催生了新的福傳創意`,en:`Learn from Church history: past epochal crises sparked new forms of evangelization`},{id:`schools`,ref:[120,121],island:`culture`,zh:`天主教學校、大學與愛德機構——在天主教徒是少數的國家，常是許多人唯一接觸教會的地方`,en:`Catholic schools, universities and charities, often the only point of contact where Catholics are few`},{id:`ecumenism`,ref:[122,123],island:null,zh:`大公合一本身就是宣講的一種形式；也向其他教會與宗教的創意學習`,en:`Ecumenism is itself a form of proclamation; learn from others' creative efforts`}]},{id:`8`,num:`VIII`,guideUrl:`/venite-ad-me/guide/8`,range:[124,137],site:[`log`,`testimonies`],title:{zh:`個人見證`,en:`Personal Testimonies`},sections:[{from:125,title:{zh:`從成癮的深淵到與基督相遇的自由`,en:`From the Abyss of Addiction to the Freedom of Encounter with Christ`}},{from:128,title:{zh:`初傳的「再覺醒」：家庭與祈禱的角色`,en:`The "Reawakening" of the Kerygma: The Role of the Family and of Prayer`}},{from:136,title:{zh:`愛德、文化與美的見證`,en:`The Witness of Charity, Culture, and Beauty`}}]},{id:`conclusion`,num:`結論`,guideUrl:`/venite-ad-me/guide/conclusion`,range:[138,144],title:{zh:`結論`,en:`Conclusion`},notes:{zh:`以復活夜點燃復活蠟、燭光一支傳一支的禮儀作結（§140–141）；邀請各團體設立為信仰傳遞代禱的時間（§143）；把信仰的傳遞託付給聖母（§144）。`,en:`Ends with the Easter Vigil image of candles lit one from another (§140–141), a call for times of prayer and intercession (§143), and Mary as teacher of transmission (§144).`}}],sun:{name:{zh:`父的愛`,en:`The Father's Love`},ref:[9,23],card:{title:{zh:`第一章 父愛的宣講`,en:`Chapter I · The Proclamation of the Father's Love`},points:[{zh:`耶穌是真光，啟示了三位一體內無條件的愛`,en:`Jesus, the true light, reveals the unconditional love within the Trinity`,ref:[10]},{zh:`沒有任何因失敗或罪而受傷的人類現實不能被恢復`,en:`No human reality marked by failure or sin is beyond restoring`,ref:[11]},{zh:`耶穌總是在路上，不建立自己的聖所或學派`,en:`Jesus is always on the move, founding no sanctuary or school of his own`,ref:[14]},{zh:`用日常生活的語言講道：動物、植物、行業、小孩的遊戲`,en:`He preaches in everyday language: animals, plants, trades, children's games`,ref:[15]},{zh:`對「最後的人」的偏愛——讓人重新相信自己的生命可以有奇蹟`,en:`His preference for 'the last' rekindles hope of a miracle in their own lives`,ref:[17]},{zh:`死刑無法熄滅真光；十字架成為福音最清晰的寶座`,en:`Execution cannot quench the true light; the cross becomes the Gospel's clearest throne`,ref:[20]},{zh:`沒有聖神就無法傳光`,en:`Without the Holy Spirit the light cannot be passed on`,ref:[23]}]}},islands:[{id:`kerygma`,num:`00`,name:{zh:`初傳`,en:`Kerygma`},tagline:{zh:`初傳不是內容，是讓人心燃燒的宣講`,en:`The first proclamation is not content but a word that sets hearts on fire`},chapter:4,ref:[72,86],axial:{q:0,r:0},palette:`gold`,ground:`dots`,tree:`olive`,mainItem:`kerygma-fire`,summary:{zh:`一切的中心。初傳（kerygma）是「耶穌基督愛你、為你捨命、如今活著陪你」的宣講，它不是要理開始前講一次就好，而是在信仰培育的每個階段都要一再聽見的「質的第一」。第四章談它怎麼引發信仰經驗、該用什麼語言說，以及它在要理裡的位置。`,en:`The centre of everything. The kerygma — Jesus Christ loves you, gave his life for you, and lives at your side — is not said once before catechesis begins; it is 'first' in quality and must be heard again at every stage. Chapter IV asks how it sparks an experience of faith, in what language, and where it belongs in catechesis.`},guideUrl:`/venite-ad-me/guide/4#kerygma`,nightLight:1,taiwan:{zh:`台灣堂區的兒童要理多半是「教科書式」，§80 的批評直接適用。`},reflect:{zh:`你的堂區最近一次「初傳」（不是要理課）是什麼時候？`,en:`When did your parish last offer a first proclamation — not a catechism class?`},selfCheckKey:`parish.adults.kerygma-in-catechesis`,items:[{id:`kerygma-fire`,name:{zh:`初傳的核心句`,en:`The heart of the first proclamation`},plain:{zh:`要理員口中要一再響起的那一句：耶穌愛你、為你捨命、活著陪你。`,en:`The line a catechist must say again and again: Jesus loves you, died for you, lives beside you.`},facts:[{zh:`它叫「第一」不是因為最早說、之後可以忘，而是因為最重要，要在要理的每個階段反覆宣講。`,en:`It is 'first' not because it comes earliest and can be dropped, but because it matters most at every stage.`,ref:[75]},{zh:`三段式過程：宣講 → 內心經驗到祂的臨在與愛 → 開始認識與愛基督的旅程。`,en:`A threefold process: proclamation → an inner experience of his presence → a journey of knowing and loving Christ.`,ref:[76]},{zh:`宣講要能「做成事」、真正觸動人心，像厄瑪烏路上門徒的心火熱起來。`,en:`It must be 'performative', truly touching hearts, like the disciples' burning hearts on the road to Emmaus.`,ref:[77]}],quote:{zh:`耶穌基督愛你，祂為救你而捨命，如今祂每天活在你身邊。`,en:`Jesus Christ loves you; he gave his life to save you.`,ref:[75]},ref:[75,76,77],model:`fire`},{id:`kerygma-response`,name:{zh:`信仰是回應，不是上課`,en:`Faith is a response, not a lesson`},plain:{zh:`天主不是在對人下指令，而是像朋友一樣說話，等人回應。`,en:`God does not issue instructions but speaks as a friend and waits for an answer.`},facts:[{zh:`梵二教導：啟示不只是傳遞教義真理，而是一場盟約式的對話。`,en:`Vatican II: revelation is not merely doctrine handed down but a covenant dialogue.`,ref:[73]},{zh:`信德行為同時有兩面：把自己整個交給基督（fides qua），以及所信的內容（fides quae）。`,en:`The act of faith has two sides: self-commitment to Christ (fides qua) and the things believed (fides quae).`,ref:[74]}],ref:[73,74],model:`dialogue`},{id:`kerygma-language`,name:{zh:`語言問題`,en:`The question of language`},plain:{zh:`信仰的語言不能冷冰冰地講概念，要先聽，再用親近的話說。`,en:`The language of faith can't be cold concepts; listen first, then speak with closeness.`},facts:[{zh:`信仰傳遞不能被困在「學院式、教條式、道德說教式」的語言裡。`,en:`Transmission must not be confined to 'scholastic', 'dogmatic' or 'moralistic' language.`,ref:[80]},{zh:`要用「親近的語言」；這種溝通不搶先說話，而是從聆聽開始。`,en:`Use 'the language of closeness'; such communication starts from listening, not speaking first.`,ref:[81]},{zh:`當語言本身成為見證，信仰的傳遞才會發生。`,en:`Transmission happens where language itself becomes testimony.`,ref:[82]}],ref:[80,81,82],model:`heart-ear`},{id:`kerygma-hierarchy`,name:{zh:`真理的等級`,en:`The hierarchy of truths`},plain:{zh:`對初來的人，先講最核心的天主的愛，別在教義細節裡迷路。`,en:`With newcomers, start from God's love at the core; don't get lost in doctrinal detail.`},facts:[{zh:`梵二《大公主義法令》11 號提出天主教教義有「真理的等級」；《福音的喜樂》把它延伸到福傳。`,en:`Unitatis Redintegratio 11 speaks of a 'hierarchy of truths'; Evangelii Gaudium extends it to proclamation.`,ref:[84]},{zh:`面對新生代、成人慕道者與「歸來者」，不要迷失在教義的眾多領域，而忘了最穩固的核心。`,en:`With new generations, adult catechumens and 'returnees', don't get lost in many doctrinal areas and lose the core.`,ref:[84]},{zh:`結論再次強調：初傳像一條金線，貫穿整個信仰寶庫的真理等級。`,en:`The conclusion adds: the kerygma runs like a golden thread through the hierarchy of truths.`,ref:[138]}],ref:[84,138],model:`stairs`},{id:`kerygma-catechesis`,name:{zh:`要理也需要初傳`,en:`Catechesis needs the kerygma too`},plain:{zh:`很多孩子來上要理時，其實還沒聽過初傳。`,en:`Many children arrive at catechism without ever having heard the first proclamation.`},facts:[{zh:`越來越多來上要理的孩子還沒聽過明確的初傳，要理於是成了重新宣講初傳的場所。`,en:`More and more children come to catechesis without an explicit first proclamation, so catechesis must offer it.`,ref:[78]},{zh:`大量孩子在完成入門聖事、或讀完天主教學校後立刻離開，顯示要理還沒找到促成持久相遇的方法。`,en:`Many drift away right after Christian initiation or Catholic school; catechesis still struggles to foster lasting encounter.`,ref:[79]}],ref:[78,79],model:`classroom`,selfCheckKey:`parish.adults.kerygma-in-catechesis`}]},{id:`family`,num:`01`,name:{zh:`家庭`,en:`Family`},tagline:{zh:`第一個、也是最根本的傳遞場所`,en:`The first and most essential place of transmission`},chapter:2,ref:[31,38],axial:{q:0,r:-1},palette:`warm`,ground:`brick`,tree:`cherry`,mainItem:`family-table`,summary:{zh:`信仰在家裡和生命一起傳下去，像餐桌上的食物一樣被分享。父母是第一位要理員，就像教孩子說母語；要理員之後才來補充。但這種「自動」的家庭傳遞，在世界許多地方已經中斷。`,en:`At home, faith is handed on together with life, shared like food at the table. Parents are the first catechists, as with a mother tongue; catechists come later. But this 'automatic' family transmission has broken down in many places.`},guideUrl:`/venite-ad-me/guide/2#family`,nightLight:.6,taiwan:{zh:`§51 的韓國觀察（父母只顧升學與職涯，要理落到祖父母身上）在台灣幾乎一樣。`},reflect:{zh:`你的孩子看過你祈禱嗎？`,en:`Have your children ever seen you pray?`},selfCheckKey:`personal.seen-praying`,items:[{id:`family-table`,name:{zh:`餐桌`,en:`The family table`},plain:{zh:`信仰在家裡像食物一樣被分享；父母是孩子的第一位要理員。`,en:`At home faith is shared like food; parents are a child's first catechists.`},facts:[{zh:`家庭是傳遞信仰的第一個、最根本的場所；良十四世說信仰像餐桌上的食物一樣被分享。`,en:`The family is the first place of transmission; Leo XIV says faith is shared like food at the family table.`,ref:[31]},{zh:`良十四世：父母是我們的第一位要理員，就像我們學母語一樣，信仰的宣講無法委託給別人。`,en:`Leo XIV: parents are our first catechists; like a mother tongue, proclaiming the faith can't be delegated.`,ref:[36]}],quote:{zh:`信仰像家庭餐桌上的食物一樣被分享。`,en:`It is shared like food at the family table.`,ref:[31]},ref:[31,36],model:`table`},{id:`family-dialect`,name:{zh:`用「方言」傳信仰`,en:`Faith in dialect`},plain:{zh:`信仰只能用家裡那種愛的語言傳下去，要理員之後才來補充。`,en:`Faith is passed on only in the home's language of love; catechists build on it later.`},facts:[{zh:`教宗方濟各 2018 年對帶孩子領洗的父母說：信仰只能用「方言」傳——爸媽、祖父母的方言。`,en:`Pope Francis told baptism parents in 2018: faith is passed on only 'in dialect' — the dialect of parents and grandparents.`,ref:[36]},{zh:`如果家裡沒有說那種愛的語言，傳遞就很難發生；要理員之後才來發展這第一次的傳遞。`,en:`If that language of love is missing at home, transmission can hardly happen; catechists come later to develop it.`,ref:[36]}],quote:{zh:`信仰的傳遞只能用「方言」來做。`,en:`Transmission of the faith can only be done 'in dialect'.`,ref:[36]},ref:[36],model:`house`},{id:`family-hands-lips`,name:{zh:`父親的手、母親的嘴唇`,en:`A father's hands, a mother's lips`},plain:{zh:`一位神父回憶：爸媽怎麼祈禱，比要理課教他更多關於天主的事。`,en:`A priest recalls that how his parents prayed taught him more about God than the catechism.`},facts:[{zh:`耶穌會士杜瓦神父（Aimé Duval）回憶：父親下工後累了，仍跪著、手肘靠在椅子上祈禱。`,en:`Jesuit Fr Aimé Duval recalls his tired father kneeling after work, elbows on a chair, to pray.`,ref:[35]},{zh:`母親太累跪不下，就抱著最小的孩子坐著默唸，眼睛一直看著每個孩子。`,en:`His mother, too tired to kneel, sat holding the youngest, lips following the prayers, eyes on each child.`,ref:[35]},{zh:`他從中學到：天主是很偉大的那一位，也是很親近、穿著工作服就能跟祂說話的那一位。`,en:`He learned that God is someone great, yet close enough to talk to in work clothes.`,ref:[35]}],ref:[35],model:`kneeling`},{id:`family-gestures`,name:{zh:`日常的小動作`,en:`Small everyday gestures`},plain:{zh:`飯前謝恩、讀福音、生日祝福、聖誕馬槽——信仰藏在家裡的日常裡。`,en:`Grace before meals, the Gospel, birthday blessings, the crib — faith lives in daily habits.`},facts:[{zh:`父母是孩子看見做門徒之美的第一個「帳幕」，見證就在簡單的日常動作裡成形。`,en:`Parents are a first 'tabernacle' where children glimpse discipleship, through simple daily gestures.`,ref:[37]},{zh:`文件列出：個人與夫妻祈禱、讀福音、主保聖人、呼求聖母、主日彌撒、朝聖、關心窮人、飯前謝恩、生日祝福、準備聖誕馬槽。`,en:`The list: personal and couple prayer, the Gospel, patron saints, Mary, Sunday Mass, shrines, the poor, grace, birthday blessings, the crib.`,ref:[37]}],ref:[37],model:`creche`,selfCheckKey:`personal.family-prayer`},{id:`family-broken`,name:{zh:`「自動」傳遞已經消失`,en:`'Automatic' transmission is gone`},plain:{zh:`家庭裡的信仰傳遞在世界許多地方已經中斷了。`,en:`Handing on faith at home has broken down in much of the world.`},facts:[{zh:`除了非洲與亞洲部分地區，家庭內的信仰傳遞在世界許多地方已經中斷，不再「自動」發生。`,en:`Except in parts of Africa and Asia, family transmission has been interrupted in many places; it is no longer 'automatic'.`,ref:[38]},{zh:`在高度世俗化的地區，越來越少父母帶孩子認識福音；許多青年在宗教冷漠中長大成人。`,en:`In highly secular regions, fewer parents introduce children to the Gospel; many grow up religiously indifferent.`,ref:[47,48]},{zh:`在前蘇聯地區，信仰是祖母直接傳給孫子，跳過了父母那一代。`,en:`In former Soviet lands, faith passed from grandmothers to grandchildren, skipping the parents.`,ref:[49]}],ref:[38,47,48,49],model:`broken-bridge`},{id:`family-baptism`,name:{zh:`洗禮與復活蠟`,en:`Baptism and the paschal candle`},plain:{zh:`父母不只把孩子帶到世上，也要把孩子帶到天主面前。`,en:`Parents bring children not only into the world but also to God.`},facts:[{zh:`拉丁禮中，點燃復活蠟的禮儀與洗禮之間有清楚的關聯：都指向要被迎進生命的光——基督。`,en:`In the Latin Church, lighting the paschal candle is linked with baptism: both point to Christ the Light.`,ref:[33]},{zh:`文件引《信德之光》轉述奧斯定：父母不只要生孩子，也要把孩子帶到天主前。`,en:`Citing Lumen Fidei, which recalls Augustine: parents bring children not only into the world but to God.`,ref:[33]}],ref:[33],model:`candle`}]},{id:`community`,num:`02`,name:{zh:`團體`,en:`Community`},tagline:{zh:`第二階段——在這裡學會用耶穌的眼睛看世界`,en:`The second stage — learning to see the world through Jesus' eyes`},chapter:2,ref:[39,42],axial:{q:1,r:-1},palette:`terracotta`,ground:`stripes`,tree:`maple`,mainItem:`community-parish`,summary:{zh:`家裡領受的信仰，到了教會團體裡成為看世界的原則；成熟的信仰就是「用耶穌的眼睛」看一切。一個人很難獨自堅持。第五章接著說：團體生活的品質、聖言小組與友誼，是今天傳遞信仰最重要的管道；而真正的斷層在成人。`,en:`What is received at home becomes, in the Church, the principle for seeing the world; mature faith sees everything 'through the eyes of Jesus'. It is hard to persevere alone. Chapter V adds: the quality of community life, Word groups and friendship are today's main channels — and the real gap is among adults.`},guideUrl:`/venite-ad-me/guide/2#community`,nightLight:.6,reflect:{zh:`一個第一次走進你堂區的人，多久會有人跟他說話？`,en:`How long before someone speaks to a first-time visitor in your parish?`},selfCheckKey:`parish.community.newcomer`,items:[{id:`community-parish`,name:{zh:`堂區`,en:`The parish`},plain:{zh:`團體是信仰傳遞的第二階段，陪人學會用耶穌的眼睛看世界。`,en:`Community is the second stage, helping people learn to see through Jesus' eyes.`},facts:[{zh:`家裡領受的見證，在團體裡透過要理、聖事、共融生活、服務弱勢與主日聚會，成為看世界的原則。`,en:`What is received at home becomes a way of seeing through catechesis, sacraments, community life, service and Sunday.`,ref:[39]},{zh:`傳遞的頂點，是能用耶穌的眼睛看自己、看別人、看世界、看天主。`,en:`The culmination: to see oneself, others, the world and God through the eyes of Jesus.`,ref:[40]},{zh:`團體的陪伴不只為了領受福音，也為了忠於所領受的——一個人很難獨自堅持。`,en:`Community is needed not only to receive the Gospel but to stay faithful; it is very hard to persevere alone.`,ref:[40]}],quote:{zh:`用耶穌的眼睛看一切。`,en:`Seeing everything "through the eyes of Jesus."`,ref:[39]},ref:[39,40],model:`church`},{id:`community-quality`,name:{zh:`團體的品質`,en:`The quality of community life`},plain:{zh:`真誠的愛與喜樂的氣氛，比任何活動都更能吸引人。`,en:`Sincere love and a joyful atmosphere attract more than any programme.`},facts:[{zh:`第一個、也最根本的觀察：團體要有真誠的愛、互相照顧、對最弱勢的開放、喜樂慶祝的氣氛、一心一德。`,en:`First and most essential: sincere love, mutual care, openness to the weakest, joy and celebration, one heart and soul.`,ref:[87]},{zh:`我們不是自給自足的；社群媒體滿足不了人作為「社會動物」的本性。`,en:`We are not self-sufficient; social media cannot satisfy our nature as 'social animals'.`,ref:[87]},{zh:`福傳的第一種形式永遠是「人傳人」。`,en:`The first form of evangelization is always 'from person to person'.`,ref:[87]}],ref:[87],model:`plaza`,selfCheckKey:`parish.community.newcomer`},{id:`community-word`,name:{zh:`聖言小組`,en:`Groups of the Word`},plain:{zh:`每個團體都該有固定聚會、一起聆聽與祈禱聖言的小組。`,en:`Every community should have regular groups that listen to and pray with the Word.`},facts:[{zh:`在每個教會團體推動固定時間聚會的小組，聆聽、默想、分享、祈禱聖言，補充主日感恩祭。`,en:`Promote in every community groups that meet regularly to listen to, meditate, share and pray the Word, alongside Sunday Mass.`,ref:[88]},{zh:`這些小組可以採用古老的「聖言誦讀」（lectio divina），也可以用現代的敘事方法。`,en:`These groups can use the ancient lectio divina as well as modern narrative methods.`,ref:[88]}],ref:[88],model:`book-circle`,selfCheckKey:`parish.community.word-group`},{id:`community-friendship`,name:{zh:`友誼`,en:`Friendship`},plain:{zh:`不管時代怎麼變，信仰最主要還是在朋友之間傳下去。`,en:`Whatever the changes, faith still travels mostly between friends.`},facts:[{zh:`儘管時代劇變，人與人的相遇仍是傳遞信仰的主要管道；最近的皈依案例也證明友誼特別重要。`,en:`Despite epochal change, person-to-person encounter remains the main channel; recent conversions show friendship matters.`,ref:[89]},{zh:`和家庭一樣，健康的友誼是真實關係的最佳場所，讓信徒彼此陪伴跟隨基督。`,en:`Along with family, healthy friendship is the setting par excellence for authentic relationships in following Christ.`,ref:[89]}],ref:[89],model:`bench-two`,selfCheckKey:`parish.community.friendship`},{id:`community-adults`,name:{zh:`成人才是斷層`,en:`Adults are the gap`},plain:{zh:`今天的傳遞特別需要成人福傳，不能只做兒童要理。`,en:`Today's transmission needs adult evangelization, not just children's catechism.`},facts:[{zh:`今天的信仰傳遞特別需要成人的福傳，要超越只做兒童與青少年要理的牧靈。`,en:`Transmission today especially requires evangelizing adults, beyond ministry focused only on children and teens.`,ref:[42]},{zh:`成人自己若不先活出信仰，怎麼把信仰傳給下一代？`,en:`How can adults pass on the faith if they do not first live it themselves?`,ref:[101]}],ref:[42,101],model:`adult-group`,selfCheckKey:`parish.adults.beyond-children`},{id:`community-baptized-not-living`,name:{zh:`受洗但不活出`,en:`Baptised but not living it`},plain:{zh:`在傳統基督宗教國家，越來越多人受了洗卻不活出洗禮的要求。`,en:`In old Christian countries, more and more people are baptised but don't live it.`},facts:[{zh:`在長期基督宗教傳統的國家，越來越多「受洗卻不活出洗禮要求」、與教會沒有實質關係的人。`,en:`In long-Christian countries there are more 'baptised whose lives do not reflect the demands of Baptism'.`,ref:[41]},{zh:`特別在青年中，不認識耶穌與福音的人也在增加。`,en:`Especially among the young, the number who do not know Jesus and the Gospel is growing.`,ref:[41]}],ref:[41],model:`empty-pew`}]},{id:`liturgy`,num:`03`,name:{zh:`禮儀`,en:`Liturgy`},tagline:{zh:`活的記憶與傳統——在這裡信仰不是被講述，而是被進入`,en:`Living memory and tradition — where faith is not described but entered`},chapter:5,ref:[90,94],axial:{q:1,r:0},palette:`violet`,ground:`brick`,tree:`pine`,mainItem:`liturgy-altar`,summary:{zh:`禮儀是慶祝並傳達基督奧蹟的特別場所，是教會生活跳動的心。在禮儀裡，我們不只是談論天主，而是與祂建立關係；信徒從不孤立，屬於一個更大的「我們」。這需要禮儀語言的教育、給年輕人的奧蹟式陪伴，以及讓人接觸禮儀傳統的豐富。`,en:`The liturgy is the privileged place where Christ's mystery is celebrated and communicated, the beating heart of Church life. There we do not merely speak of God but enter into relationship with him, never alone but within a larger 'we'. It calls for education in liturgical language, mystagogy for the young, and access to the richness of the tradition.`},guideUrl:`/venite-ad-me/guide/5#liturgy`,nightLight:.6,taiwan:{zh:`台灣堂區的彌撒常被視為「義務」，§90 說信仰透過禮儀的舉行本身傳遞，是直接的對照。`},reflect:{zh:`你的堂區做過「禮儀教育」嗎？不是解釋規矩，是解釋為什麼。`,en:`Has your parish ever offered liturgical formation — not the rules, but the why?`},selfCheckKey:`parish.liturgy.formation`,items:[{id:`liturgy-altar`,name:{zh:`祭台`,en:`The altar`},plain:{zh:`在禮儀裡，我們不是談論天主，而是與祂建立關係。`,en:`In the liturgy we don't talk about God; we enter into relationship with him.`},facts:[{zh:`禮儀是慶祝並以聖事方式傳達救恩奧蹟的特別場所，是教會生活跳動的心。`,en:`The liturgy is the privileged place where the mystery is celebrated and communicated, the beating heart of Church life.`,ref:[90]},{zh:`禮儀先是一種信仰經驗，然後才是教導；它不只「告知」，而是從內塑造人。`,en:`Liturgy is first an experience of faith, before it is teaching; it shapes from within rather than merely informing.`,ref:[90]},{zh:`在禮儀裡，信仰透過舉行本身傳遞：不只談論天主，而是與祂建立關係。`,en:`In the liturgy faith is transmitted performatively: we do not merely speak of God but relate to him.`,ref:[90]}],quote:{zh:`我們不只是談論天主，而是與祂建立關係。`,en:`We do not merely speak of God but enter into a relationship with him.`,ref:[90]},ref:[90],model:`altar`,selfCheckKey:`parish.liturgy.formation`},{id:`liturgy-we`,name:{zh:`「我們」先於「我」`,en:`'We' before 'I'`},plain:{zh:`在禮儀裡沒有人是孤單的，這正是對個人主義的解藥。`,en:`No one is alone in the liturgy — an antidote to individualism.`},facts:[{zh:`在禮儀中，信徒從不孤立，而是屬於一個先於他、陪伴他、超越他的「我們」。`,en:`In the liturgy the believer is never isolated but part of a 'we' that precedes, accompanies and transcends them.`,ref:[91]},{zh:`這個團體幅度是對自私、個人主義生活方式的強力解藥；也和本地化密切相關。`,en:`This communal dimension is a powerful antidote to individualism, and closely linked to inculturation.`,ref:[91]}],ref:[91],model:`procession`},{id:`liturgy-lex`,name:{zh:`lex orandi, lex credendi`,en:`Lex orandi, lex credendi`},plain:{zh:`怎麼祈禱，就怎麼相信——禮儀不能只是形式化的演出。`,en:`As we pray, so we believe — liturgy cannot be mere formal performance.`},facts:[{zh:`依照古老格言「祈禱的法則就是信仰的法則」，禮儀對信仰傳遞至關重要，不能淪為形式化的演出。`,en:`Following lex orandi, lex credendi, liturgy is crucial and cannot be reduced to formal performance.`,ref:[92]},{zh:`完全有意識的參與，前提是有足夠的「禮儀語言的教育」。`,en:`Fully conscious participation presupposes an adequate education in liturgical language.`,ref:[92]},{zh:`年輕的奧斯定聽到教會的聖歌而感動落淚，多年後仍記得。`,en:`The young Augustine wept at the Church's hymns and remembered it years later.`,ref:[92]}],ref:[92],model:`choir`,selfCheckKey:`parish.liturgy.formation`},{id:`liturgy-mystagogy`,name:{zh:`給年輕人的奧蹟引導`,en:`Mystagogy for the young`},plain:{zh:`慶典要特別用心，並陪年輕人理解、活出他們所慶祝的。`,en:`Celebrate with special care, and help the young understand and live what they celebrate.`},facts:[{zh:`禮儀行動是教會使命的生成之源，讓團體以被恩寵轉化的生命說明心中的希望。`,en:`Liturgical action is the generative source of the Church's mission, giving an account of hope.`,ref:[92]},{zh:`慶典要特別用心；年輕世代需要奧蹟式（mystagogy）的陪伴，才能理解並活出所慶祝的。`,en:`Special care in celebrations, and mystagogical accompaniment of the young, so they understand and live it.`,ref:[92]}],ref:[92],model:`lantern-path`,selfCheckKey:`parish.liturgy.mystagogy`},{id:`liturgy-gaze`,name:{zh:`用眼睛參與`,en:`Taking part by seeing`},plain:{zh:`參與禮儀不只靠聽和說，也可以「住在凝視裡」。`,en:`Taking part isn't only listening and speaking; one can also dwell in seeing.`},facts:[{zh:`瓜爾蒂尼（Guardini）在西西里的蒙雷阿萊看到群眾幾乎不看書，全神「住在凝視裡」。`,en:`Guardini, at Monreale in Sicily, saw a crowd hardly reading, all 'living in the gaze'.`,ref:[93]},{zh:`他說北歐只認識「聽、說、動作」的參與，卻失去了在觀看中迎接神聖的能力。`,en:`He said Northern Europe knew only participation by listening, speaking and gesture, and had lost participation by seeing.`,ref:[93]},{zh:`民間敬禮也有自己的禮儀感，依不同文化有不同形式。`,en:`Popular piety has its own liturgical sensibility, varying by culture.`,ref:[93]}],ref:[93],model:`mosaic-dome`,selfCheckKey:`parish.beauty.visible-liturgy`},{id:`liturgy-heritage`,name:{zh:`禮儀傳統的多樣性`,en:`The richness of liturgical heritage`},plain:{zh:`讓信徒接觸天主教禮儀的豐富傳統，例如多樣的音樂風格。`,en:`Let the faithful meet the richness of Catholic liturgy, such as its many musical styles.`},facts:[{zh:`在遵守現行禮規下，牧者應讓信徒（包括慕道與歸來者）接觸禮儀遺產的豐富，例如多樣的音樂風格。`,en:`Within current norms, pastors should show the richness of the liturgical heritage, e.g. its variety of musical styles.`,ref:[94]},{zh:`西方正在失去集體的儀式記憶，但人對儀式的人類學需求並沒有消失。`,en:`The West is losing collective ritual memory, yet the anthropological need for ritual remains.`,ref:[94]},{zh:`也要特別用教會的祝福，伴隨人生的重要階段。`,en:`The significant stages of life should be accompanied with the Church's blessing.`,ref:[94]}],ref:[94],model:`organ`,selfCheckKey:`parish.liturgy.heritage`}]},{id:`witness`,num:`04`,name:{zh:`見證`,en:`Witness`},tagline:{zh:`三個面向——聖德、親近、優先選擇窮人`,en:`Three dimensions — holiness, closeness, the preferential option for the poor`},chapter:5,ref:[95,97],axial:{q:0,r:1},palette:`coral`,ground:`dots`,tree:`fruit`,mainItem:`witness-saints`,summary:{zh:`沒有什麼比成員的聖德更讓教會在傳遞信仰時可信。見證有三個面向：聖德（每個基督徒的普通聖召）、對每個人的親近（款待、聆聽、溫柔），以及優先照顧窮人——窮人不是社會問題，而是「我們自己人」。愛德與宣講合一，基督徒生活的美就更清楚。`,en:`Nothing makes the Church more credible than the holiness of her members. Witness has three dimensions: holiness (the ordinary vocation of every Christian), closeness to everyone (hospitality, listening, tenderness), and preferential care for the poor — not a social problem but 'one of us'. When charity and proclamation are one, the beauty of the Christian way shines.`},guideUrl:`/venite-ad-me/guide/5#witness`,nightLight:.6,reflect:{zh:`你的團體對窮人的具體服務，外人看得到嗎？`,en:`Can outsiders see your community's concrete service to the poor?`},selfCheckKey:`parish.witness.visible-service`,items:[{id:`witness-saints`,name:{zh:`聖德`,en:`Holiness`},plain:{zh:`聖德是教會最有吸引力的面貌，也是每個人的日常聖召。`,en:`Holiness is the Church's most attractive face — and everyone's ordinary calling.`},facts:[{zh:`遇見一位典範基督徒的人，總會想發現那份生命的祕密；沒有什麼比成員的聖德更讓教會可信。`,en:`Meeting an exemplary Christian makes people seek the secret of that life; nothing makes the Church more credible.`,ref:[95]},{zh:`文件只舉亞西西的聖方濟與加爾各答的聖德蘭為例。`,en:`The text recalls just two figures: Francis of Assisi and Teresa of Calcutta.`,ref:[95]},{zh:`《你們要歡喜踴躍》：成聖不必是主教或修會士——結婚的、工作的、當父母祖父母的，都能就地成聖。`,en:`Gaudete et Exsultate: holiness isn't only for clergy — spouses, workers, parents and grandparents can be holy where they are.`,ref:[95]}],quote:{zh:`聖德是教會最有吸引力的面貌。`,en:`Holiness is the most attractive face of the Church.`,ref:[95]},ref:[95],model:`two-figures`,selfCheckKey:`parish.witness.asked-why`},{id:`witness-closeness`,name:{zh:`親近`,en:`Closeness`},plain:{zh:`一個傾聽的動作加上一句信仰的話，就能打開大門。`,en:`A gesture of listening plus a word of faith can open wide the door.`},facts:[{zh:`親近是用款待、善意、聆聽、溫和與溫柔建立起來的。`,en:`Closeness is built through hospitality, kindness, listening, gentleness and tenderness.`,ref:[96]},{zh:`引古羅馬作家泰倫斯：凡是人的事，對我都不陌生；對信徒也應如此。`,en:`Citing Terence: nothing human is foreign to me — nor should it be to believers.`,ref:[96]},{zh:`對身心受苦的人，一個傾聽與溫柔的動作，加上一句信仰的話，可以為基督的光敞開大門。`,en:`For those who suffer, listening and tenderness with a word of faith can open the door to Christ's light.`,ref:[96]}],ref:[96],model:`doorway`,selfCheckKey:`parish.witness.listening-silence`},{id:`witness-poor`,name:{zh:`窮人是家人`,en:`The poor are family`},plain:{zh:`窮人不是社會問題，而是「我們自己人」。`,en:`The poor are not a social problem but 'one of us'.`},facts:[{zh:`良十四世勸諭《我愛了你》（Dilexi Te）：基督徒不能把窮人只當成社會問題，他們是我們的「家人」。`,en:`Leo XIV, Dilexi Te: no Christian can see the poor simply as a social problem; they are family.`,ref:[97]},{zh:`與窮人的關係，也不能被化約成教會的另一項活動或功能。`,en:`Our relationship with the poor cannot be reduced to just another Church activity.`,ref:[97]},{zh:`愛德與宣講合一，基督徒道路完整的美就更清楚。`,en:`In the unity of charity and proclamation, the full beauty of the Christian way shines.`,ref:[97]}],quote:{zh:`他們是「我們自己人」。`,en:`They are 'one of us.'`,ref:[97]},ref:[97],model:`soup-kitchen`,selfCheckKey:`parish.witness.charity-and-proclamation`},{id:`witness-myanmar`,name:{zh:`緬甸的沉默`,en:`Myanmar's silence`},plain:{zh:`在戰亂的國家，教會用傾聽的沉默親近最窮的人，不分宗教。`,en:`In a war-torn country, the Church draws near the poorest in listening silence.`},facts:[{zh:`緬甸主教 2026 年 6 月 2 日述職訪問時分享：在多重衝突的國家，教會親近最窮的人。`,en:`Myanmar's bishops, on their ad limina visit (2 June 2026), described closeness to the poorest amid conflict.`,ref:[97]},{zh:`有時只是傾聽的沉默，不分宗教——緬甸以佛教徒為主。`,en:`Sometimes simply through the silence of listening, regardless of religion, in a mainly Buddhist nation.`,ref:[97]},{zh:`正是這份親近，讓非基督徒想知道背後的理由，信徒也因此有機會明說自己對耶穌的經驗。`,en:`This closeness makes others ask why, giving believers the chance to speak of Jesus.`,ref:[97]}],ref:[97],model:`tent`,voice:`myanmar`}]},{id:`beauty`,num:`05`,name:{zh:`美與藝術`,en:`Beauty & Art`},tagline:{zh:`via pulchritudinis——話語到不了的地方，美可以`,en:`Via pulchritudinis — beauty reaches where words cannot`},chapter:5,ref:[98,99],axial:{q:-1,r:1},palette:`rose`,ground:`stripes`,tree:`willow`,mainItem:`beauty-stage`,summary:{zh:`談信仰傳遞時，要為人對美、愛與超越的渴望留一席之地。文學與詩能抓住連被科技分心的心靈；音樂特別是一座通往天主的橋，不是慶典的裝飾，而是藉吸引力運作的傳教工具。文件也明確呼籲信徒藝術家與作家做特別的創作努力。`,en:`Any talk of transmission must make room for the human longing for beauty, love and transcendence. Literature and poetry can captivate even distracted minds; music above all is a bridge to God — not decoration but a missionary tool that works by attraction. The text explicitly urges believing artists and writers to a special creative effort.`},guideUrl:`/venite-ad-me/guide/5#beauty`,nightLight:.5,reflect:{zh:`你的堂區最近一次「因為美」而吸引人，是什麼？`,en:`When did your parish last draw someone in because of beauty?`},selfCheckKey:`parish.beauty.recent-beauty`,items:[{id:`beauty-stage`,name:{zh:`舞台`,en:`The stage`},plain:{zh:`人對美、愛與超越的渴望，在信仰傳遞裡應有一席之地。`,en:`The longing for beauty, love and transcendence deserves a place in transmission.`},facts:[{zh:`談信仰傳遞時，要為人類創造力的各種表現留空間，它們表達了人心對美、愛與超越的渴望。`,en:`Make room for human creativity, which gives form to the heart's yearning for beauty, love and transcendence.`,ref:[98]},{zh:`巴爾塔薩（Balthasar）強調：一切靈性的感知與追求，都應伴隨美學的向度。`,en:`Balthasar: an aesthetic element must accompany all spiritual perception and striving.`,ref:[98]}],ref:[98],model:`stage`},{id:`beauty-music`,name:{zh:`音樂是橋`,en:`Music is a bridge`},plain:{zh:`音樂不是裝飾，而是藉吸引力運作的傳教工具。`,en:`Music is not decoration but a missionary tool that works through attraction.`},facts:[{zh:`音樂是「美之路」的特別表達，是傳遞信仰的基本語言，能觸動人心最深的弦。`,en:`Music, a privileged expression of the via pulchritudinis, is an essential language of transmission.`,ref:[99]},{zh:`它不是慶典的美學點綴，而是藉吸引力運作的傳教工具，在話語難以到達之處讓復活者的光榮被感知。`,en:`Not an aesthetic embellishment but a missionary tool working by attraction, where words struggle to reach.`,ref:[99]}],quote:{zh:`音樂像一座引領我們走向天主的橋。`,en:`Music is like a bridge that leads us to God.`,ref:[99]},ref:[99],model:`piano`,selfCheckKey:`parish.liturgy.music-as-mission`},{id:`beauty-artists`,name:{zh:`給藝術家的呼籲`,en:`A call to artists`},plain:{zh:`文件明確呼籲信徒藝術家與作家，為信仰之美做特別的創作。`,en:`The text urges believing artists and writers to a special creative effort.`},facts:[{zh:`文件敦促信徒藝術家與作家做特別的創作努力，彰顯基督信仰與靈性經驗的美。`,en:`It urges believing artists and writers to a special creative effort to show the beauty of faith.`,ref:[99]},{zh:`透過音樂，信仰找到純口語宣講單獨達不到的表達途徑。`,en:`Through music, faith finds avenues that purely verbal proclamation does not always reach.`,ref:[99]}],ref:[99],model:`easel`,selfCheckKey:`parish.beauty.artists`},{id:`beauty-literature`,name:{zh:`文學與詩`,en:`Literature and poetry`},plain:{zh:`能喚起崇高驚奇的作品，連被科技分心的心都能抓住。`,en:`Works that evoke sublime wonder can captivate even tech-distracted minds.`},facts:[{zh:`許多文學與詩的作品喚起崇高的驚奇，能吸引連被現代通訊科技分心的心靈。`,en:`Many works of literature and poetry evoke sublime wonder and captivate minds distracted by technology.`,ref:[98]},{zh:`美在人心裡常是以「受折磨的方式」存在的渴望，值得被認真看待。`,en:`This yearning often dwells in the heart 'in a tormented way' and deserves attention.`,ref:[98]}],ref:[98],model:`library`,selfCheckKey:`parish.beauty.literature`}]},{id:`lifestages`,num:`06`,name:{zh:`人生階段`,en:`Stages of Life`},tagline:{zh:`很多人只在洗禮、婚禮、殯葬時走進教會`,en:`Many people enter a church only for baptisms, weddings and funerals`},chapter:5,ref:[100,101],axial:{q:-1,r:0},palette:`sage`,ground:`dots`,tree:`bamboo`,mainItem:`life-milestones`,summary:{zh:`童年、青春期、青年、成年、老年，每個階段都是重新領受「出生」這份禮物，宣講要配合階段調整。許多人只在洗禮、婚禮、殯葬時接觸教會——這是宣講初傳的珍貴機會。過去初傳幾乎只對年輕人；今天，成人牧靈成了新的、充滿挑戰的牧靈領域。`,en:`Childhood, adolescence, youth, adulthood and old age each re-appropriate the gift of birth, and proclamation should fit each stage. Many meet the Church only at baptisms, weddings and funerals — precious chances for the kerygma. Once aimed almost only at the young, it now faces a new, complex field: the pastoral care of adults.`},guideUrl:`/venite-ad-me/guide/5#lifestages`,nightLight:.5,reflect:{zh:`你的堂區殯葬彌撒，講道是在講亡者，還是在講基督？`,en:`At funerals in your parish, does the homily speak of the deceased, or of Christ?`},selfCheckKey:`parish.lifestages.funeral-homily`,items:[{id:`life-milestones`,name:{zh:`三個門檻`,en:`Three thresholds`},plain:{zh:`洗禮、婚禮、殯葬，是向久未進堂的人宣講初傳的機會。`,en:`Baptisms, weddings and funerals are chances to proclaim the kerygma.`},facts:[{zh:`許多人只在洗禮、婚禮、殯葬這些人生關鍵時刻的慶典中接觸教會。`,en:`Many encounter the Church only at celebrations of key moments: baptisms, weddings and funerals.`,ref:[100]},{zh:`這是用觸動人心的初傳接觸他們的珍貴機會，要避免說出不促成任何相遇的話。`,en:`A precious chance to reach them with a heart-touching kerygma, avoiding words that foster no encounter.`,ref:[100]}],ref:[100],model:`three-doors`,selfCheckKey:`parish.lifestages.thresholds`},{id:`life-stages`,name:{zh:`五個階段`,en:`Five stages`},plain:{zh:`人生每個階段都不同，宣講也要跟著調整。`,en:`Each stage of life is different, and so should proclamation be.`},facts:[{zh:`童年、青春期、青年、成年、老年，每個階段都像是對「出生」這份禮物的持續再領受。`,en:`Childhood, adolescence, youth, adulthood, old age: each is a 'reappropriation' of the gift of birth.`,ref:[100]},{zh:`教會團體要發展更留意不同人生階段的宣講，考慮各階段帶來的成長與更新。`,en:`The community must develop a proclamation more attentive to each stage's growth and renewal.`,ref:[100]}],ref:[100],model:`stair-figures`,selfCheckKey:`parish.lifestages.by-stage`},{id:`life-adults`,name:{zh:`成人牧靈是新戰場`,en:`Adult ministry is a new frontier`},plain:{zh:`要陪伴那些小時候受洗、離開教會、卻聽不懂教會語言的成人。`,en:`Accompany adults baptised young, now distant, who struggle with the Church's language.`},facts:[{zh:`過去在傳統基督宗教國家，初傳幾乎只對年輕人宣講。`,en:`In the past, in old Christian countries, the kerygma was aimed almost only at the young.`,ref:[101]},{zh:`今天急需陪伴那些自幼受洗、遠離團體、內心有召叫卻聽不懂教會語言的人。`,en:`Today we must accompany those baptised young, living apart, who feel a call yet struggle with Church language.`,ref:[101]},{zh:`下一代的信仰傳遞，取決於成人的福傳。`,en:`Transmission to the young depends on the evangelization of adults.`,ref:[101]}],ref:[101],model:`lantern-adult`,selfCheckKey:`parish.lifestages.returnees`},{id:`life-synodal`,name:{zh:`更共議、更傳教的教會`,en:`A more synodal, missionary Church`},plain:{zh:`都市的碎片化與偏鄉的孤立，挑戰整個教會更共議、更傳教。`,en:`Urban fragmentation and rural isolation challenge the Church to be more synodal and missionary.`},facts:[{zh:`各種存在性的貧窮——特別在高度碎片化的都市與孤立的偏鄉——帶來更多困難。`,en:`Existential poverty, especially in fragmented cities and isolated rural areas, adds further difficulty.`,ref:[101]},{zh:`這一切挑戰整個教會更加共議、更有傳教精神，特別是培養聖神在天主子民中激發的神恩。`,en:`All this urges the Church to be more synodal and missionary, fostering the charisms of the Spirit.`,ref:[101]}],ref:[101],model:`round-table`}]},{id:`culture`,num:`07`,name:{zh:`文化與本地化`,en:`Culture & Inculturation`},tagline:{zh:`沒有成為文化的信仰，是沒有被完全接納的信仰`,en:`A faith that does not become culture has not been fully embraced`},chapter:6,ref:[102,109],axial:{q:-1,r:-1},palette:`ochre`,ground:`brick`,tree:`palm`,mainItem:`culture-roots`,summary:{zh:`信仰的傳遞和它在具體文化中的本地化分不開。福傳要深入根部，不是表面的漆；福音降生於本地文化，本地文化也進入教會生活。要觸及每個社會層面與次文化，也要向學術圈宣講。第三章談亞洲與非洲的處境，第七章補上民間敬禮。`,en:`Transmitting the faith cannot be separated from its inculturation. Evangelize down to the roots, not as a coat of paint; the Gospel takes flesh in local cultures and they enter the Church's life. Reach every level and subculture, and the academic world too. Chapter III covers Asia and Africa; Chapter VII adds popular piety.`},guideUrl:`/venite-ad-me/guide/6#culture`,nightLight:.5,taiwan:{zh:`§66 的「亞洲教會是社會學上明確的少數團體、身分感強」就是台灣。`},reflect:{zh:`你堂區的禮儀、音樂、建築，有多少是「台灣的」？`,en:`How much of your parish's liturgy, music and architecture is truly local?`},items:[{id:`culture-roots`,name:{zh:`信仰要成為文化`,en:`Faith must become culture`},plain:{zh:`福傳要深入文化的根部，而不是刷一層表面的漆。`,en:`Evangelize down to the roots of a culture, not as a surface coat of paint.`},facts:[{zh:`若望保祿二世：沒有成為文化的信仰，是沒被完全接納、沒被想透、沒被忠實活出的信仰。`,en:`John Paul II: a faith that does not become culture has not been fully embraced, thought through or lived.`,ref:[102]},{zh:`他引保祿六世：要福傳人類文化，不是裝飾性的表面油漆，而是深入到根部。`,en:`Quoting Paul VI: evangelize culture not decoratively, like a coat of paint, but down to the roots.`,ref:[102]},{zh:`信仰的傳遞和它在特定處境中的本地化，在某種程度上是分不開的。`,en:`Transmitting the faith is in some way inseparable from its inculturation in a specific context.`,ref:[103]}],quote:{zh:`沒有成為文化的信仰，是沒有被完全接納的信仰。`,en:`A faith that does not become culture has not been fully embraced.`,ref:[102]},ref:[102,103],model:`big-tree`},{id:`culture-inculturation`,name:{zh:`本地化`,en:`Inculturation`},plain:{zh:`福音降生於本地文化，本地文化也走進教會生活。`,en:`The Gospel takes flesh in local culture, and local culture enters Church life.`},facts:[{zh:`本地化是「福音降生於本地文化，也把這些文化引入教會生活」（引若望保祿二世《斯拉夫人的使徒》通諭）。`,en:`Inculturation is the Gospel's incarnation in native cultures and their entry into Church life (Slavorum Apostoli).`,ref:[104]},{zh:`這是伴隨整個傳教生活的漫長旅程，主教負責分辨與鼓勵（引《救主使命》通諭）。`,en:`It is a slow journey accompanying all missionary life; bishops provide discernment (Redemptoris Missio).`,ref:[104]},{zh:`信仰觸及一個民族的文化根源時，傳遞就變得更容易、更豐碩。`,en:`Where faith touches a people's cultural roots, transmission becomes easier and more fruitful.`,ref:[107]}],ref:[104,107],model:`loom`},{id:`culture-subcultures`,name:{zh:`次文化`,en:`Subcultures`},plain:{zh:`都市邊緣青年、移工、季節工、小村落——每一層都要被觸及。`,en:`Youth on the urban fringe, migrants, seasonal workers, villages — every level must be reached.`},facts:[{zh:`我們福傳的不是「地方」，而是人；也要把福音翻譯進青年、窮人等社會群體的文化形式。`,en:`We evangelize people, not 'places'; translate the Gospel into the forms of youth, the poor and other groups.`,ref:[105]},{zh:`城市裡有各自語言與文化的群體，要觸及次文化：都市邊緣青年、移民社群、季節工、小村落居民。`,en:`Reach subcultures: young people on urban peripheries, migrant communities, seasonal workers, small villages.`,ref:[106]},{zh:`國際神學委員會未來五年將研究傳遞信仰的文化形式——文件在此只是簡述。`,en:`The International Theological Commission will study cultural forms of transmission over the next five years.`,ref:[106]}],ref:[105,106],model:`market`,evidence:`pending`},{id:`culture-asia`,name:{zh:`亞洲：少數、強身分、古文明`,en:`Asia: minority, strong identity, ancient cultures`},plain:{zh:`亞洲教會是少數，身分感強；但信仰要從社會慣性變成個人選擇。`,en:`Asian Churches are minorities with strong identity; faith must become a personal choice.`},facts:[{zh:`因為信徒常是少數，亞洲教會發展成社會學上明確的團體，有強烈的身分感（菲律賓、東帝汶是例外）。`,en:`As minorities, Asian Churches became well-defined communities with strong identity (the Philippines and Timor-Leste excepted).`,ref:[66]},{zh:`要超越僅憑「社會慣性的歸屬」的信仰，使它成為個人、有意識的選擇。`,en:`Move beyond Christianity based on the inertia of social affiliation, toward a personal, conscious choice.`,ref:[66]},{zh:`在印度、中國等古文明，要對話該文化對真善美的理解；宣講要優先用敘事，而非抽象概念。`,en:`In ancient cultures like India and China, engage their sense of truth, goodness and beauty; favour narrative over abstraction.`,ref:[66]}],ref:[66],model:`pagoda`},{id:`culture-academy`,name:{zh:`學術界`,en:`The academic world`},plain:{zh:`福音也要向專業、科學與學術圈宣講。`,en:`The Gospel must also be proclaimed in professional, scientific and academic circles.`},facts:[{zh:`引《福音的喜樂》：向學術圈宣講，意味信仰、理性與科學的相遇，發展有創意的護教。`,en:`Citing Evangelii Gaudium: proclaiming to academic circles means faith, reason and science meeting in creative apologetics.`,ref:[108]},{zh:`學術研究至多是信仰的預備（praeambula fidei），但合理的說明能幫助喚起人心中的大問題。`,en:`Research is at most a preparation (praeambula fidei), but reasonable presentation helps awaken the great questions.`,ref:[108]},{zh:`教會的社會訓導是特別好的例子：它和社會、甚至非信徒進行開放的對話。`,en:`The Church's social doctrine is a prime example, opening dialogue with society and even non-believers.`,ref:[109]}],ref:[108,109],model:`university`},{id:`culture-africa`,name:{zh:`非洲：本地化不完全，信仰就停在表層`,en:`Africa: incomplete inculturation, shallow faith`},plain:{zh:`福音若沒有深入本地文化，信仰就沒有根、容易被外力帶走。`,en:`Without deep inculturation, faith has no roots and is easily swept away.`},facts:[{zh:`南部非洲主教：基督宗教傳得廣，卻常停在表層，需要在非洲靈修中更深地降生。`,en:`Southern African bishops: Christianity spread widely but stays shallow, needing deeper roots in African spirituality.`,ref:[52]},{zh:`奈及利亞主教：本地神職人員是傳統價值與天主教教導之間的橋樑。`,en:`Nigerian bishops: local clergy bridge traditional values and Catholic teaching.`,ref:[67]},{zh:`坦尚尼亞主教：小型基督徒團體是祈禱、要理與團契的基本單位，「團體如家庭」。`,en:`Tanzanian bishops: Small Christian Communities are the basic unit — 'community-as-family'.`,ref:[67]}],ref:[52,67],model:`village-circle`},{id:`culture-popular-piety`,added:!0,name:{zh:`民間敬禮`,en:`Popular piety`},plain:{zh:`民間敬禮是本地化的果實，至今仍是傳遞信仰的重要途徑。`,en:`Popular piety, fruit of inculturation, is still an important way of handing on faith.`},facts:[{zh:`第七章列出的第一個關注領域：民間敬禮有些面向需要成熟，但它仍是今天傳遞信仰的重要方法。`,en:`Chapter VII's first area: popular piety needs maturing in places, but remains an important means of transmission.`,ref:[111]},{zh:`每個真正的信仰本地化，都會產生民間的信仰表達；它有一股不可低估的福傳力量。`,en:`Every authentic inculturation gives rise to popular expressions of faith, with an evangelizing power not to underestimate.`,ref:[112]},{zh:`朝聖與加入善會對年輕一代很有吸引力，例如最近在西班牙；這可以成為基督之光的管道。`,en:`Pilgrimages and confraternities attract the young, as recently in Spain, and can become a channel for Christ's light.`,ref:[113]}],ref:[111,112,113],model:`wayside-shrine`}]},{id:`digital`,num:`08`,name:{zh:`數位世界`,en:`Digital World`},tagline:{zh:`挑戰不是科技的，是人類學的`,en:`The challenge is not technological but anthropological`},chapter:3,ref:[59,62],axial:{q:1,r:1},palette:`teal`,ground:`stripes`,tree:`pine-small`,mainItem:`digital-tower`,summary:{zh:`數位科技是時代變遷最明顯的記號。即時與過度刺激的文化讓人對追求真理感到疲乏；AI 模擬人的聲音、面孔與友誼，侵入人際關係最深處。數位文化重塑了空間、時間與權威，也可能造出「自己組裝」的信仰——但它同時帶來前所未有的福傳機會。`,en:`Digital technology is the clearest sign of the epochal change. A culture of immediacy and hyper-stimulation breeds fatigue about seeking truth; AI simulates voices, faces and friendship, reaching into human relationships. Digital culture reshapes space, time and authority and can produce a 'do-it-yourself' faith — yet it also opens unprecedented chances to evangelize.`},guideUrl:`/venite-ad-me/guide/3#digital`,nightLight:.8,windowColor:`cold`,taiwan:{zh:`堂區或教會學校開設 AI 課程、講座時，§59–62 是很好的引言材料。`},reflect:{zh:`你的堂區在網路上「在場」嗎？在場的是什麼？`,en:`Is your parish present online? What is it presenting?`},selfCheckKey:`parish.adults.online-kerygma`,items:[{id:`digital-tower`,name:{zh:`訊號塔`,en:`The signal tower`},plain:{zh:`數位科技是時代變遷最明顯的記號，也讓人對追求真理感到疲乏。`,en:`Digital tech is the clearest sign of our epoch, and it wearies us of seeking truth.`},facts:[{zh:`數位科技的擴散，無疑是我們正在經歷的時代變遷最明顯的記號之一。`,en:`The spread of digital technology is undoubtedly one of the clearest signs of the epochal change.`,ref:[59]},{zh:`良十四世通諭《偉大的人類》（Magnifica Humanitas）：即時與過度刺激的文化，讓人對追求真理感到疲乏、無聊、冷漠。`,en:`Leo XIV, Magnifica Humanitas: a culture of immediacy and hyper-stimulation breeds fatigue and apathy about truth.`,ref:[59]},{zh:`世界主教會議（2023）：數位文化根本地改變了我們理解現實、與自己、他人、甚至天主建立關係的方式。`,en:`Synod (2023): digital culture fundamentally changes how we see reality and relate to ourselves, others and God.`,ref:[59]}],ref:[59],model:`tower`},{id:`digital-ai`,name:{zh:`AI 是人類學問題`,en:`AI is an anthropological question`},plain:{zh:`AI 模擬聲音、面孔、同理與友誼，侵入人際關係最深的層次。`,en:`AI simulates voices, faces, empathy and friendship, reaching the depths of relationship.`},facts:[{zh:`AI 模擬人的聲音與面孔、智慧與知識、意識與責任、同理與友誼，侵入人際關係這個最深的溝通層次。`,en:`AI simulates voices and faces, wisdom, empathy and friendship, encroaching on human relationships themselves.`,ref:[59]},{zh:`良十四世（2026 世界傳播日文告）：挑戰不是科技的，而是人類學的；這對信仰的本地化影響重大。`,en:`Leo XIV (2026 Communications Day): the challenge is anthropological, not technological — with consequences for inculturation.`,ref:[59]}],quote:{zh:`挑戰不是科技的，而是人類學的。`,en:`The challenge, therefore, is not technological, but anthropological.`,ref:[59]},ref:[59],model:`robot`},{id:`digital-space-time-authority`,name:{zh:`三個被重塑的範疇`,en:`Three categories reshaped`},plain:{zh:`空間、時間、權威這三個「傳統」的基礎，都被數位文化改寫了。`,en:`Space, time and authority — the foundations of tradition — are rewritten by digital culture.`},facts:[{zh:`空間：對具體在地的歸屬感變弱（但沒有完全消失），人同時活在全球網絡裡。`,en:`Space: belonging to a local place weakens (though not entirely), as people live in a global network.`,ref:[61]},{zh:`時間：一切被壓成「永恆的現在」，失去真正的歷史感，人更容易被一時的潮流帶走。`,en:`Time: everything flattens into an 'eternal present', losing a sense of history and following passing trends.`,ref:[61]},{zh:`權威：所有聲音被放在同一平面、只比傳播力，傳統機構的公信力受到嚴重威脅。`,en:`Authority: all voices sit on one level, judged by reach alone, threatening traditional institutions' credibility.`,ref:[62]}],ref:[61,62],model:`three-pillars`},{id:`digital-diy-faith`,name:{zh:`DIY 信仰`,en:`Do-it-yourself faith`},plain:{zh:`網路可能讓信仰脫離生活，變成照個人口味組裝的東西。`,en:`Online, faith can detach from life and become assembled to personal taste.`},facts:[{zh:`數位世界讓人分享生命見證、讓要理內容傳得比以往更廣，為福傳開啟前所未有的可能。`,en:`The digital world lets people share testimonies and spreads catechesis further than ever before.`,ref:[60]},{zh:`但信仰的邀請也可能變得脫離身體、脫離具體生活，或被少數高聲量者的意識形態綁住。`,en:`But the invitation to faith can become disembodied, detached from life, or tied to vocal minorities' ideologies.`,ref:[60]},{zh:`結果可能是照個人口味、而非教會教導組裝起來的「DIY 信仰」。`,en:`The result can be a 'do-it-yourself' faith shaped by personal taste rather than Church teaching.`,ref:[60]}],ref:[60],model:`kiosk`,selfCheckKey:`personal.online-diy`},{id:`digital-opportunity`,name:{zh:`新機會`,en:`New opportunities`},plain:{zh:`法國年輕人也透過社群媒體認識信徒，進而走向洗禮。`,en:`Young people in France have met believers on social media and moved toward baptism.`},facts:[{zh:`法國成人洗禮者的動機之一，是與其他信徒的接觸——面對面，也透過社群媒體。`,en:`Among French adult converts' reasons: contact with believers, in person and through social media.`,ref:[63]},{zh:`口耳相傳、邀請、朝聖，以及在新媒體上的主動臨在，都是回應人重新浮現的意義追尋的方式。`,en:`Word of mouth, invitations, pilgrimages and active presence in new media all answer a re-emerging search for meaning.`,ref:[65]}],ref:[63,65],model:`phone-glow`,selfCheckKey:`parish.adults.online-kerygma`}]},{id:`my-parish`,num:`09`,name:{zh:`我的堂區`,en:`My Parish`},tagline:{zh:`填自我檢視，長出你的堂區`,en:`Take the self-check and grow your parish`},chapter:null,ref:null,axial:{q:-2,r:1},palette:`dynamic`,ground:`dots`,tree:`maple`,bridgeTo:`lifestages`,bridgeDecks:13,dynamic:!0,emptyModel:`signboard`,summary:{zh:`這座島一開始是空的。填完堂區版自我檢視，島上會依六個面向的分數長出對應的建物；分數越高，夜晚亮的窗越多。`,en:`This island starts empty. Complete the parish self-check and buildings grow according to your six scores; the higher the scores, the more windows glow at night.`},guideUrl:`/venite-ad-me/self-check/parish`,nightLight:0,items:[]}],lines:[{id:`sun-to-kerygma`,from:`sun`,to:`kerygma`,carry:`light`,beam:!0,walkers:[],label:{zh:`父的愛 → 初傳`,en:`Father's love → Kerygma`},evidence:`official`,ref:[9,10,11,23],note:{zh:`一切的光源是父的愛；沒有聖神就無法傳光。`,en:`All light comes from the Father's love; without the Spirit it cannot be passed on.`}},{id:`kerygma-to-all`,from:`kerygma`,to:[`family`,`community`,`liturgy`,`witness`,`beauty`,`lifestages`,`culture`,`digital`],carry:`candle`,walkers:[{role:`catechist`,n:2}],label:{zh:`初傳 → 每座島`,en:`Kerygma → every island`},evidence:`official`,ref:[75,83],note:{zh:`初傳是「質的第一」，要在要理的每個階段一再宣講；一切培育都是更深進入初傳。`,en:`The kerygma is first in quality, proclaimed at every stage; all formation enters it more deeply.`}},{id:`family-to-community`,from:`family`,to:`community`,carry:`candle`,walkers:[{role:`parent`,n:2},{role:`child`,n:2}],label:{zh:`家庭 → 團體`,en:`Family → Community`},evidence:`official`,ref:[39],note:{zh:`家裡領受的，在團體裡成為看世界的原則。`,en:`What is received at home becomes, in the community, a way of seeing the world.`}},{id:`community-to-family`,from:`community`,to:`family`,carry:`bread`,walkers:[{role:`catechist`,n:2}],label:{zh:`團體 → 家庭`,en:`Community → Family`},evidence:`official`,ref:[33,36],note:{zh:`教會與家庭要深度合作；要理員「之後才來」補充家庭的第一次傳遞。`,en:`Church and family must cooperate; catechists come 'later' to develop the family's first transmission.`}},{id:`community-to-liturgy`,from:`community`,to:`liturgy`,carry:`book`,walkers:[{role:`any`,n:4}],label:{zh:`團體 → 禮儀`,en:`Community → Liturgy`},evidence:`official`,ref:[88,90],note:{zh:`聖言小組補充主日感恩祭；團體在禮儀中被聖言與生命之糧滋養。`,en:`Word groups complement Sunday Mass; in the liturgy the community is fed by Word and Bread.`}},{id:`liturgy-to-witness`,from:`liturgy`,to:`witness`,carry:`candle`,walkers:[{role:`youth`,n:3}],label:{zh:`禮儀 → 見證`,en:`Liturgy → Witness`},evidence:`official`,ref:[92],note:{zh:`禮儀行動是教會使命的生成之源。`,en:`The liturgical action is the generative source of the Church's mission.`}},{id:`witness-to-community`,from:`witness`,to:`community`,carry:`soup`,walkers:[{role:`poor`,n:2},{role:`volunteer`,n:2}],label:{zh:`見證 → 團體`,en:`Witness → Community`},evidence:`official`,ref:[97],note:{zh:`愛德與宣講合一，基督徒道路的美就更清楚。`,en:`In the unity of charity and proclamation, the beauty of the Christian way shines.`}},{id:`beauty-to-liturgy`,from:`beauty`,to:`liturgy`,carry:`music`,walkers:[{role:`artist`,n:2}],label:{zh:`美 → 禮儀`,en:`Beauty → Liturgy`},evidence:`official`,ref:[99],note:{zh:`音樂是通往天主的橋，不是慶典的裝飾。`,en:`Music is a bridge to God, not a decoration of celebrations.`}},{id:`lifestages-to-kerygma`,from:`lifestages`,to:`kerygma`,carry:`lantern`,walkers:[{role:`returnee`,n:3}],label:{zh:`人生階段 → 初傳`,en:`Stages of life → Kerygma`},evidence:`official`,ref:[100,101],note:{zh:`洗禮、婚禮、殯葬這些人生門檻，是宣講初傳的機會。`,en:`Life's thresholds — baptisms, weddings, funerals — are chances for the kerygma.`}},{id:`culture-to-all`,from:`culture`,to:[`community`,`liturgy`],carry:`thread`,walkers:[{role:`migrant`,n:2},{role:`farmer`,n:1}],label:{zh:`文化 → 團體／禮儀`,en:`Culture → Community / Liturgy`},evidence:`thematic`,ref:[103,104,105,106,107],note:{zh:`信仰觸及文化根源時，傳遞變得更容易、更結實。`,en:`Where faith touches cultural roots, transmission becomes easier and more fruitful.`}},{id:`digital-to-community`,from:`digital`,to:`community`,carry:`phone`,walkers:[{role:`youth`,n:3}],label:{zh:`數位 → 團體`,en:`Digital → Community`},evidence:`thematic`,ref:[60,63,65],note:{zh:`社群媒體能帶人走向團體，但也可能讓信仰脫離身體。`,en:`Social media can lead people to community, but can also disembody faith.`}},{id:`community-to-digital`,from:`community`,to:`digital`,carry:`candle`,walkers:[{role:`catechist`,n:1}],label:{zh:`團體 → 數位`,en:`Community → Digital`},evidence:`pending`,ref:[60,61,62],note:{zh:`教會在數位世界要怎麼「在場」，文件沒有給出結論。`,en:`How the Church should be 'present' online, the text leaves open.`}},{id:`grandparent-bridge`,from:`family`,to:`family`,loop:!0,carry:`rosary`,walkers:[{role:`grandparent`,n:2},{role:`child`,n:2}],label:{zh:`祖父母橋`,en:`The grandparents' bridge`},evidence:`official`,ref:[49,50,51],note:{zh:`祖母傳孫子、跳過父母那一代——從前蘇聯、哥倫比亞到韓國都看得到。`,en:`Grandmothers to grandchildren, skipping parents — from former Soviet lands to Colombia and Korea.`}}],clock:{startMinute:600,minutesPerSecond:10},dayCycle:[{id:`christendom`,minute:720,icon:`☀`,name:{zh:`基督宗教社會`,en:`Christendom`},desc:{zh:`家庭、學校、文化與教會彼此連續，信仰幾乎「自動」地一代傳一代。`,en:`Family, school, culture and Church were continuous; faith passed on almost 'automatically'.`},ref:[50,53],highlight:[`family-gestures`,`liturgy-altar`,`community-parish`],nightLightOverride:{family:1,community:1,liturgy:1,witness:1,beauty:1,lifestages:1,culture:1,digital:1}},{id:`secularization`,minute:1065,icon:`🌇`,name:{zh:`世俗化`,en:`Secularisation`},desc:{zh:`個人主義與「自我主權」高漲，信仰被推進私人領域，不參與也不必解釋。`,en:`Individualism and the 'sovereignty of the self' rise; faith goes private, and absence needs no excuse.`},ref:[55,56,57,58],highlight:[`family-broken`,`community-baptized-not-living`,`digital-diy-faith`],nightLightOverride:{family:.3,community:.4,liturgy:.5,witness:.5,beauty:.5,lifestages:.5,culture:.5,digital:.5}},{id:`post-christian`,minute:1260,icon:`🌙`,name:{zh:`後基督宗教`,en:`Post-Christian`},desc:{zh:`傳統機構失去權威，一切被壓成永恆的現在；有些地方已可稱為後基督宗教社會。`,en:`Traditional institutions lose authority, all flattens into an eternal present: post-Christian societies.`},ref:[55,61,62],highlight:[`digital-space-time-authority`,`community-adults`],nightLightOverride:{family:.15,community:.25,liturgy:.35,witness:.6,beauty:.4,lifestages:.3,culture:.5,digital:.9}},{id:`new-dawn`,minute:390,icon:`🌅`,name:{zh:`新的黎明`,en:`A new dawn`},desc:{zh:`法國成人洗禮一年增 28%、十年翻三倍，多數不到 40 歲；但新教友能否堅持是問題。`,en:`French adult baptisms up 28% in a year, tripled in a decade, mostly under 40; perseverance is the issue.`},ref:[63,64,65],highlight:[`digital-opportunity`,`community-friendship`,`life-adults`,`kerygma-fire`],nightLightOverride:{kerygma:1,family:.35,community:.7,liturgy:.55,witness:.8,beauty:.6,lifestages:.5,culture:.7,digital:.9}}],voices:[{id:`former-ussr`,country:{zh:`俄羅斯／前蘇聯地區`,en:`Russia / former Soviet Union`},region:`europe`,kind:`islet`,source:`bishops`,pos:{angle:324,dist:21},gist:{zh:`信仰從祖母直接傳到孫子，父母那一代被跳過了。`,en:`Faith passed from grandmothers straight to grandchildren, skipping the parents' generation.`},ref:[49],relatedIsland:`family`},{id:`albania`,country:{zh:`阿爾巴尼亞`,en:`Albania`},region:`europe`,kind:`islet`,source:`bishops`,pos:{angle:333,dist:27},gist:{zh:`同樣看見中間世代的斷層。`,en:`The same gap in the middle generation.`},ref:[49],relatedIsland:`family`},{id:`hungary-gc`,country:{zh:`匈牙利希臘禮天主教會`,en:`Hungarian Greek Catholic Church`},region:`europe`,kind:`islet`,source:`bishops`,pos:{angle:342,dist:19},gist:{zh:`不能再假設父母會自動傳信仰；過去有效的方法，現在結不出同樣的果實。`,en:`Parents can no longer be assumed to pass on the faith; what worked before no longer bears fruit.`},ref:[49],relatedIsland:`family`},{id:`romania`,country:{zh:`羅馬尼亞`,en:`Romania`},region:`europe`,kind:`islet`,source:`bishops`,pos:{angle:351,dist:25},gist:{zh:`不參與宗教生活，社會已不再覺得需要解釋。`,en:`Not practising religion is no longer seen as something to explain.`},ref:[55],relatedIsland:`community`},{id:`spain`,country:{zh:`西班牙`,en:`Spain`},region:`europe`,kind:`islet`,source:`bishops`,pos:{angle:0,dist:29},gist:{zh:`個人與家庭既承受文化危機的後果，也反過來成了危機的原因。`,en:`Individuals and families suffer the cultural crisis and, in turn, feed it.`},ref:[58],relatedIsland:`family`},{id:`austria`,country:{zh:`奧地利`,en:`Austria`},region:`europe`,kind:`islet`,source:`bishops`,pos:{angle:9,dist:20},gist:{zh:`宗教被私人化、被推出公共領域；但信仰不可能只埋在心裡而不影響世界。`,en:`Religion is privatised and pushed out of public life, yet faith cannot be buried in the heart without affecting the world.`},ref:[58],relatedIsland:`culture`},{id:`france-canada`,country:{zh:`法國／加拿大`,en:`France / Canada`},region:`europe`,kind:`islet`,source:`document`,pos:{angle:18,dist:26},gist:{zh:`世俗主義甚至寫進法律，限制人在公共空間表達信仰。`,en:`Secularism reaches into law, limiting public expression of faith.`},ref:[58],relatedIsland:`culture`},{id:`belgium`,country:{zh:`比利時`,en:`Belgium`},region:`europe`,kind:`lighthouse`,source:`bishops`,pos:{angle:27,dist:22},gist:{zh:`當前的時代變遷也是正面的機會，讓人有意識地選擇深化信仰。`,en:`The present epochal change is also a positive chance to choose, consciously, to deepen one's faith.`},ref:[63],relatedIsland:`kerygma`},{id:`france`,country:{zh:`法國`,en:`France`},region:`europe`,kind:`sailboat`,source:`bishops`,pos:{angle:36,dist:28},gist:{zh:`2026 年成人洗禮比前一年多 28%，是 2016 年的三倍以上；多數不到 40 歲。`,en:`Adult baptisms rose 28% in 2026, over three times the 2016 figure; most are under 40.`},ref:[63],relatedIsland:`lifestages`},{id:`korea`,country:{zh:`韓國`,en:`Korea`},region:`asia`,kind:`lighthouse`,source:`bishops`,pos:{angle:58,dist:21},gist:{zh:`父母只顧孩子的升學與職涯，兒童與青年的要理多半落到祖父母身上。`,en:`Parents focus on grades and careers, so grandparents carry most of the catechesis.`},ref:[51],relatedIsland:`family`},{id:`malaysia-sg-brunei`,country:{zh:`馬來西亞／新加坡／汶萊`,en:`Malaysia / Singapore / Brunei`},region:`asia`,kind:`islet`,source:`bishops`,pos:{angle:66,dist:27},gist:{zh:`職涯優先，靈修培育越來越交給個人自己用媒體處理。`,en:`Careers come first; spiritual formation is left to private use of media.`},ref:[51],relatedIsland:`digital`},{id:`bangladesh`,country:{zh:`孟加拉`,en:`Bangladesh`},region:`asia`,kind:`islet`,source:`bishops`,pos:{angle:74,dist:19},gist:{zh:`同樣的問題，在以穆斯林為主的社會裡更加嚴峻。`,en:`The same problem, sharpened by a mainly Muslim society.`},ref:[51],relatedIsland:`culture`},{id:`japan`,country:{zh:`日本`,en:`Japan`},region:`asia`,kind:`islet`,source:`bishops`,pos:{angle:82,dist:25},gist:{zh:`堂區要理遇到困難，跨宗教婚姻普遍，家中的傳遞因此受阻。`,en:`Parish catechesis struggles and interreligious marriages are common, hindering home transmission.`},ref:[51],relatedIsland:`family`},{id:`central-asia`,country:{zh:`中亞`,en:`Central Asia`},region:`asia`,kind:`islet`,source:`bishops`,pos:{angle:90,dist:29},gist:{zh:`曾屬蘇聯集團的少數教會，處境近似東歐撐過數十年的「沉默的教會」。`,en:`A minority Church in former Soviet lands, much like Eastern Europe's "Church of Silence".`},ref:[51],relatedIsland:`community`},{id:`maronite`,country:{zh:`安提約基雅馬龍尼禮宗主教區`,en:`Maronite Patriarchate of Antioch`},region:`asia`,kind:`islet`,source:`bishops`,added:!0,pos:{angle:98,dist:22},gist:{zh:`要超越「社會慣性的歸屬」，讓信仰成為個人有意識的選擇。`,en:`Move beyond belonging out of social inertia, toward a personal, conscious choice.`},ref:[66],relatedIsland:`culture`},{id:`philippines-timor`,country:{zh:`菲律賓／東帝汶`,en:`Philippines / Timor-Leste`},region:`asia`,kind:`islet`,source:`document`,pos:{angle:106,dist:28},gist:{zh:`亞洲少數以天主教徒為多數的社會，是「少數教會」的例外。`,en:`Asia's notable exceptions, where Catholics are the majority.`},ref:[66],relatedIsland:`culture`},{id:`india-china`,country:{zh:`印度／中國`,en:`India / China`},region:`asia`,kind:`islet`,source:`document`,pos:{angle:114,dist:20},gist:{zh:`古老文明有自己理解真善美的方式；宣講要優先用敘事，而非抽象概念。`,en:`Ancient cultures see truth, goodness and beauty in their own way; favour narrative over abstraction.`},ref:[66],relatedIsland:`culture`},{id:`myanmar`,country:{zh:`緬甸`,en:`Myanmar`},region:`asia`,kind:`lighthouse`,source:`bishops`,pos:{angle:122,dist:26},gist:{zh:`用傾聽的沉默親近最窮的人，不分宗教；這份親近讓非基督徒想知道原因。`,en:`Closeness to the poorest in listening silence, regardless of religion, makes others ask why.`},ref:[97],relatedIsland:`witness`},{id:`southern-africa`,country:{zh:`南部非洲`,en:`Southern Africa`},region:`africa`,kind:`lighthouse`,source:`bishops`,pos:{angle:150,dist:24},gist:{zh:`基督宗教傳得廣卻常停在表層，福音需要更深地降生在非洲靈修裡。`,en:`Christianity spread widely but often stays shallow; the Gospel must root deeper in African spirituality.`},ref:[52],relatedIsland:`culture`},{id:`zambia`,country:{zh:`尚比亞`,en:`Zambia`},region:`africa`,kind:`islet`,source:`bishops`,added:!0,pos:{angle:160,dist:29},gist:{zh:`各種宗教運動的競爭越來越激烈，連受洗者也回到傳統宗教實踐。`,en:`Competition from religious movements grows, and even the baptised return to traditional practices.`},ref:[52],relatedIsland:`witness`},{id:`nigeria`,country:{zh:`奈及利亞`,en:`Nigeria`},region:`africa`,kind:`lighthouse`,source:`bishops`,pos:{angle:170,dist:21},gist:{zh:`本地神職人員是傳統價值與天主教教導之間的橋樑。`,en:`Local clergy bridge traditional values and Catholic teaching.`},ref:[67],relatedIsland:`culture`},{id:`tanzania`,country:{zh:`坦尚尼亞`,en:`Tanzania`},region:`africa`,kind:`lighthouse`,source:`bishops`,pos:{angle:180,dist:27},gist:{zh:`小型基督徒團體是祈禱、要理與團契的基本單位：「團體如家庭」。`,en:`Small Christian Communities are the basic unit of prayer, catechesis and fellowship.`},ref:[67],relatedIsland:`community`},{id:`ivory-coast`,country:{zh:`象牙海岸`,en:`Côte d'Ivoire`},region:`africa`,kind:`islet`,source:`bishops`,pos:{angle:190,dist:19},gist:{zh:`人們轉向應許安康與幸福的運動，不少受洗者回到傳統與秘術實踐。`,en:`People seek movements promising well-being and happiness; many baptised return to traditional and esoteric practices.`},ref:[68],relatedIsland:`witness`},{id:`drc`,country:{zh:`剛果民主共和國`,en:`DR Congo`},region:`africa`,kind:`islet`,source:`bishops`,pos:{angle:200,dist:25},gist:{zh:`除了基要主義團體的壓力，還要面對伊斯蘭主義團體的強勢擴張。`,en:`Besides fundamentalist pressure, communities face the aggressive spread of Islamist groups.`},ref:[70],relatedIsland:`witness`},{id:`ghana`,country:{zh:`迦納`,en:`Ghana`},region:`africa`,kind:`lighthouse`,source:`bishops`,added:!0,pos:{angle:210,dist:22},gist:{zh:`天主教教育大大加強了信仰傳遞，是兒童、青年甚至成人持續培育的管道。`,en:`Catholic education strongly supports transmission, forming children, youth and adults.`},ref:[120],relatedIsland:`culture`},{id:`chile`,country:{zh:`智利`,en:`Chile`},region:`americas`,kind:`lighthouse`,source:`bishops`,pos:{angle:242,dist:23},gist:{zh:`家庭、學校、文化與教會的連續性斷了；信仰成了要自由接受、被陪伴、在生命中驗證的提案。`,en:`The old continuity is gone; faith is a proposal to be freely accepted, accompanied and tested in life.`},ref:[50,63],relatedIsland:`lifestages`},{id:`antilles`,country:{zh:`安地列斯`,en:`Antilles`},region:`americas`,kind:`islet`,source:`bishops`,pos:{angle:250,dist:29},gist:{zh:`世代之間的連續性變弱，特別在要理與聖事實踐上。`,en:`Continuity between generations weakens, especially in catechesis and sacraments.`},ref:[50],relatedIsland:`community`},{id:`panama`,country:{zh:`巴拿馬`,en:`Panama`},region:`americas`,kind:`islet`,source:`bishops`,pos:{angle:258,dist:20},gist:{zh:`信仰在民間表達與人生大事裡仍很活躍，卻已不再在家中自然傳遞。`,en:`Faith thrives in popular expressions, but is no longer passed on naturally at home.`},ref:[50],relatedIsland:`family`},{id:`colombia`,country:{zh:`哥倫比亞`,en:`Colombia`},region:`americas`,kind:`islet`,source:`bishops`,pos:{angle:266,dist:26},gist:{zh:`祖父母補上家庭要理的缺口，與堂區一起分擔。`,en:`Grandparents fill gaps in home catechesis, alongside the parish.`},ref:[50],relatedIsland:`family`},{id:`peru-amazon`,country:{zh:`秘魯亞馬遜地區`,en:`Peruvian Amazon`},region:`americas`,kind:`islet`,source:`bishops`,pos:{angle:274,dist:19},gist:{zh:`因本地文化的緣故，孩子的洗禮延到較大的年齡。`,en:`For cultural reasons, children's baptism is postponed until they are older.`},ref:[50],relatedIsland:`culture`},{id:`usa`,country:{zh:`美國`,en:`United States`},region:`americas`,kind:`islet`,source:`bishops`,pos:{angle:282,dist:25},gist:{zh:`信徒被文化吸收多於被信仰吸收；社群媒體比信仰更塑造天主教徒的想法。`,en:`The faithful are absorbed more by culture than by faith; social media shapes them more.`},ref:[55],relatedIsland:`digital`},{id:`brazil`,country:{zh:`巴西`,en:`Brazil`},region:`americas`,kind:`islet`,source:`bishops`,pos:{angle:290,dist:29},gist:{zh:`歸屬感流失加上主觀的宗教性，洗禮不再自動通往成熟的信仰。`,en:`Lost belonging and subjective religiosity: baptism no longer leads automatically to mature faith.`},ref:[58],relatedIsland:`community`},{id:`venezuela`,country:{zh:`委內瑞拉`,en:`Venezuela`},region:`americas`,kind:`islet`,source:`bishops`,added:!0,pos:{angle:298,dist:21},gist:{zh:`學校的宗教教育課程，讓學校與堂區活動彼此銜接。`,en:`School religious education links school and parish life.`},ref:[120],relatedIsland:`community`}],logEvents:{depart:{zh:`{role}從{from}出發，帶著{carry}`,en:`{role} sets out from {from}, carrying {carry}`},arrive:{zh:`{role}抵達{to}`,en:`{role} arrives at {to}`},light:[{zh:`在{to}，一支蠟燭被點燃`,en:`In {to}, a candle is lit`},{zh:`{role}把{carry}交給了{to}的人`,en:`{role} hands {carry} to someone in {to}`}],testimonyIntervalSec:90,testimonyTag:`TESTIMONY`},testimonies:{ref:[124,137],intro:{zh:`文件說這些見證多半不是偉大事蹟或奇蹟，而是日常裡恩寵的作為，讓每個人都能在其中認出自己的經驗（§124）。`,en:`The text says these are mostly not great feats or miracles but grace at work in daily life, in which readers may recognise their own story (§124).`},sections:[{id:`addiction`,title:{zh:`從成癮的深淵到與基督相遇的自由`,en:`From the Abyss of Addiction to the Freedom of Encounter with Christ`},ref:[125,126,127],island:`witness`,summary:{zh:`三則見證都從谷底開始：一位曾陷入毒品與幫派的青年，在以祈禱為核心的戒治中心開始悔改，後來成為陪伴別人的人；一位青少年在滑手機時偶然看到一段祈禱，走向洗禮；一位監獄神父看見受刑人在信任與傾聽的關係裡，遇見寬恕人、扶起人的天主。`,en:`All three begin at rock bottom: a young man lost to drugs and gangs begins conversion in a prayer-centred rehab and later accompanies others; a teenager meets a prayer while scrolling and seeks baptism; a prison chaplain sees inmates meet a forgiving God through trust and listening.`},items:[{ref:[125],place:{zh:`哥倫比亞`,en:`Colombia`},line:{zh:`一位曾流落街頭的青年，在祈禱中重新被愛，如今陪伴其他年輕人。`,en:`A young man once on the streets, loved anew in prayer, now walks with other young people.`}},{ref:[126],place:{zh:`比利時`,en:`Belgium`},line:{zh:`滑手機時偶然看到的一段祈禱，成了一個青少年生命中最重要的呼喚。`,en:`A prayer met while scrolling became the most important call of a teenager's life.`}},{ref:[127],place:{zh:`加拿大`,en:`Canada`},line:{zh:`在監獄裡，請求洗禮常是尋找新的開始；相遇來自信任與傾聽。`,en:`In prison, asking for baptism is often a search for a new start, born of trust and listening.`}}]},{id:`reawakening`,title:{zh:`初傳的「再覺醒」：家庭與祈禱的角色`,en:`The "Reawakening" of the Kerygma: The Role of the Family and of Prayer`},ref:[128,129,130,131,132,133,134,135],island:`family`,summary:{zh:`八則見證裡，信仰常從家庭的縫隙重新醒來：陪女兒上要理、喪母多年的家長、在聖言中鼓起勇氣向父親求寬恕的母親、因未婚妻或妻子而認識教會的男士、在避靜中發現天主是父的婦女、在聖體中重新認出耶穌、再次祈禱的要理老師。`,en:`In eight stories, faith reawakens through the cracks of family life: a grieving parent at a daughter's catechism, a mother who, through the Word, finds courage to ask her father's forgiveness, men drawn by a fiancée or wife, a woman who meets God as Father on retreat, a catechist who rediscovers Jesus in the Eucharist and prays again.`},items:[{ref:[128],place:{zh:`智利`,en:`Chile`},line:{zh:`一位自稱無神論的家長，陪小女兒上要理時，在感恩祭中與基督重逢。`,en:`A self-declared atheist parent, attending a daughter's catechism, met Christ again in the Eucharist.`}},{ref:[129],place:{zh:`斯洛伐克`,en:`Slovakia`},line:{zh:`在團體與聖言中，一位母親找到勇氣向父親求寬恕，如今和丈夫一起把信仰傳給孩子。`,en:`In community and the Word, a mother found courage to ask her father's forgiveness; now she and her husband pass faith to their children.`}},{ref:[130],place:{zh:`美國`,en:`United States`},line:{zh:`為了理解未婚妻的信仰，他走進一個接納人的堂區，準備在復活夜領洗。`,en:`To understand his fiancée's faith, he found a welcoming parish and awaits baptism at Easter.`}},{ref:[131],place:{zh:`日本`,en:`Japan`},line:{zh:`孩子出生後，他開始問自己想傳給孩子什麼，幾年後領了洗。`,en:`After his child was born, he asked what he wanted to pass on — and years later was baptised.`}},{ref:[132],place:{zh:`安哥拉`,en:`Angola`},line:{zh:`婚前一場坦率的對話，讓一位對宗教冷漠的未婚夫開始上要理、領洗。`,en:`A frank conversation before marriage led an indifferent fiancé to catechism and baptism.`}},{ref:[133],place:{zh:`波蘭`,en:`Poland`},line:{zh:`在一次信仰更新的避靜中，她發現天主是白白愛人的父，死去的信仰活了過來。`,en:`On a retreat of renewal she met God as a Father who loves freely; her dead faith came alive.`}},{ref:[134],place:{zh:`法國`,en:`France`},line:{zh:`在宗教空白中長大的學生，夜裡在宿舍感到祂就在身邊，最後決定領受入門聖事。`,en:`A student raised in spiritual silence sensed God close by one night and chose the sacraments.`}},{ref:[135],place:{zh:`牙買加`,en:`Jamaica`},line:{zh:`一位要理老師曾停止祈禱，後來在聖體中重新認出耶穌，祈禱從「求」變成「給」。`,en:`A catechist who stopped praying recognised Jesus in the Eucharist; her prayer turned from asking to giving.`}}]},{id:`charity-beauty`,title:{zh:`愛德、文化與美的見證`,en:`The Witness of Charity, Culture, and Beauty`},ref:[136,137],island:`beauty`,summary:{zh:`美與愛德也是通往信仰的路：一位在無神論家庭長大的科學系學生，在音樂、大自然與主教座堂裡感受到天主，最後是團體先接納了這位學生；一位佛教家庭出身的越南青年，在免費英文班感受到基督徒的善意，多年後報名慕道。`,en:`Beauty and charity also lead to faith: a science student from an atheist home sensed God in music, nature and a cathedral, and found the community welcomed them first; a young Vietnamese from a Buddhist family felt Christians' kindness in a free English class and later became a catechumen.`},items:[{ref:[136],place:{zh:`瑞士`,en:`Switzerland`},line:{zh:`在無神論家庭長大的學生，第一次跪下祈禱時就迎接了天主——然後是團體先接納了這位學生。`,en:`Raised by atheists, a student welcomed God when first kneeling to pray — and the community welcomed them first.`}},{ref:[137],place:{zh:`越南／馬來西亞`,en:`Vietnam / Malaysia`},line:{zh:`一堂充滿善意的免費英文課，課堂影片最後問「天主在哪裡？」，這個問題留在一位佛教家庭青年的心裡。`,en:`In a free English class full of kindness, a video ended with the question 'Where is God?' — and it stayed with a young man from a Buddhist family.`}}]}]},introContext:[{zh:`文體是「省思」（Considerations），不是「教義註釋」；用較論述性的風格，不打算對問題下定論。`,en:`The genre is 'Considerations', not a Doctrinal Note: discursive, not claiming to settle the matter.`,ref:[8]},{zh:`教宗方濟各多次催促教義部寫這份省思；良十四世繼位、禧年與 2033 年救贖禧年讓撰寫加快。`,en:`Pope Francis repeatedly urged it; Leo XIV's election, the Jubilee and the 2033 Jubilee of Redemption sped it up.`,ref:[3]},{zh:`許多國家主教團提供了寶貴的資料與見證。`,en:`Many national Bishops' Conferences contributed valuable material and testimonies.`,ref:[6,7]},{zh:`本文件談的是信仰經驗（fides qua）的喚醒，不打算完整處理信仰寶庫（depositum fidei）的傳遞。`,en:`It addresses awakening the experience of faith (fides qua), not the full transmission of the depositum fidei.`,ref:[5]},{zh:`良十四世於 2026 年 8 月 21 日批准，10 月 22 日（聖若望保祿二世紀念日）發布。`,en:`Approved by Leo XIV on 21 August 2026; published 22 October 2026, memorial of St John Paul II.`,ref:[144]}]};export{t};